          // console.log(formData.get('files'))
          let config = {
            headers: {
              "Content-Type": "multipart/form-data",
            },
          };
          axiosUpload
            .post(
              this.$url.url_5000 + "/model_view/algorithm_upload",
              formData,
              config
            )
            .then((response) => {
              if (response.data.code == 200) {
                this.jiaForm.algorithm_version = response.data.data.algorithm_version;
